 ('어린이놀이시설', '어린이 놀이기구 목재부분 마모로 인해 조임볼트가 헐거워져 아이들 기구 이용시 떨어짐 위험', '제38조', '산업안전보건법 제38조(안전조치)', NULL, NULL, ARRAY['부식된 목재 교체 및 보수와 도장 후 다시 볼트조임완료']::text[], 200365);
